// Lấy callback_data từ Telegram Trigger.
// Tùy phiên bản n8n, dữ liệu có thể nằm trực tiếp trong $json
// hoặc nằm bên trong $json.callback_query.
const callbackData =
  $json.data ??
  $json.callback_query?.data ??
  '';

// Callback data dự kiến:
// claim|NOTION_PAGE_ID
const [action, notionPageId] = callbackData.split('|');

// Nếu callback không đúng cấu trúc thì dừng workflow và báo lỗi.
if (!action || !notionPageId) {
  throw new Error(`Callback data không hợp lệ: ${callbackData}`);
}

// Lấy thông tin người đã bấm nút.
const callbackFrom =
  $json.from ??
  $json.callback_query?.from ??
  {};

// Lấy thông tin tin nhắn Telegram chứa nút "Nhận lead".
const callbackMessage =
  $json.message ??
  $json.callback_query?.message ??
  {};

// Ưu tiên username.
// Nếu không có username thì dùng họ tên Telegram.
const fullName = [
  callbackFrom.first_name,
  callbackFrom.last_name,
]
  .filter(Boolean)
  .join(' ')
  .trim();

const saleName =
  callbackFrom.username
    ? `@${callbackFrom.username}`
    : fullName || 'Sale';

// Trả dữ liệu sạch cho các node phía sau.
return {
  action: action,

  notion_page_id: notionPageId,

  sale_telegram_id: String(
    callbackFrom.id ?? ''
  ),

  sale_name: saleName,

  callback_query_id:
    $json.id ??
    $json.callback_query?.id ??
    '',

  telegram_chat_id:
    callbackMessage.chat?.id ??
    '',

  telegram_message_id:
    callbackMessage.message_id ??
    '',

  original_message_text:
    callbackMessage.text ??
    callbackMessage.caption ??
    '',
};

